package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.order.infrastructure.*;import com.yuegang.zhihui.order.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class OrderConfiguration{@Bean OrderService orderService(DataSource d){return new OrderService(d);}@Bean OrderQueryService orderQueryService(DataSource d){return new OrderQueryService(d);}@Bean OrderInventoryFacade orderInventoryFacade(OrderService o,InventoryClient i,DataSource d){return new OrderInventoryFacade(o,i,d);}@Bean InventoryClient inventoryClient(@Value("${ygh.inventory.internal-base-url}")String b,@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new InventoryClient(b,k);}finally{Arrays.fill(k,(byte)0);}}@Bean CartService cartService(DataSource d){return new CartService(d);}@Bean CheckoutService checkoutService(@Value("${ygh.product.internal-base-url}")String b){return new CheckoutService(b);}@Bean OrderUserResolver orderUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new OrderUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
